        # Increase forward force to 20N to help robot move into activation zone
        fx = 20.0 if x < 5.0 else 10.0 * (7.0 - x) - 5.0 * vxd
        fy = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Check if in activation zone and velocity is low enough to switch to unlock phase
