        # Apply backward force strictly less than -34N
        fx_cmd = cfg["bfx"] - 1.0  # -35N
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Adjust force based on speed to maintain low speed
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p
        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1
        # Switch to escape after 60 steps in unlock phase
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
