        # Apply forward force to move towards exit zone
        fx, fy = 15.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp
        # Switch to hold once in exit zone
        if x > _exit_x_min(sandbox) + 2.5:
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        # Apply minimal force to maintain position
        fx, fy = 0.0, w_comp
    sandbox.apply_agent_force(fx, fy)

