            # Front whisker is close, move backward
            fx -= 10.0
        if up < 1.0:
            fy += 5.0
        if down < 1.0:
            fy -= 5.0

        # Check if in activation zone
        in_activation = (cfg["act_lo"] <= x <= cfg["act_hi"])
        if in_activation and abs(vxd) < 0.3:
            state["unlock_steps"] += 1
        else:
            state["unlock_steps"] = 0

        if state["unlock_steps"] >= 5:
            state["phase"] = "UNLOCK"
            state["t"] = 0
    elif state["phase"] == "UNLOCK":
        fx_cmd = -35.0  # Strictly below threshold
        fy_cmd = 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Adjust based on whisker readings
        if up < 1.0:
            fy_cmd += 5.0
        if down < 1.0:
            fy_cmd -= 5.0

        # Adjust horizontal force based on whisker readings
        if front < 1.0:
            fx_cmd -= 10.0

        spd = math.hypot(vx_p, vy_p)

        # Adjust force based on speed
        if spd >= cfg["bspd"] * 0.99:
            horiz = -1.5 * vx_p
            if horiz > 0:
                horiz = 0
            fx_cmd += horiz
            fy_cmd -= 1.5 * vy_p

        fx, fy = fx_cmd, fy_cmd
        state["t"] += 1

        # Switch to escape after 60 steps
        if state["t"] > 60:
            state["phase"] = "ESCAPE"
    elif state["phase"] == "ESCAPE":
        fx, fy = 35.0, 50.0 * (ty - y) - 20.0 * vyd + w_comp

        # Adjust vertical force based on whisker readings
        if up < 1.0:
            fy += 5.0
        if down < 1.0:
            fy -= 5.0

        # Adjust horizontal force based on whisker readings
        if front < 1.0:
            fx -= 10.0

        # Transition to hold when in exit zone
        if x >= _exit_x_min(sandbox):
            state["phase"] = "HOLD"
    elif state["phase"] == "HOLD":
        fx, fy = 0.0, w_comp

        # Track hold steps
        if x >= _exit_x_min(sandbox):
            state["hold_steps"] += 1
        else:
            state["hold_steps"] = 0

        # Check if hold is complete
        if state["hold_steps"] >= 5:
            # Mission complete, no action needed
            pass

    # Check structural impulse limit
    impulse_magnitude = math.sqrt(fx**2 + fy**2) * dt
    state["total_impulse"] += impulse_magnitude
    if state["total_impulse"] > 250.0:
        fx = 0.0
        fy = 0.0

    sandbox.apply_agent_force(fx, fy)

import math


ACTIVATION_X_MAX = 10.0
ACTIVATION_X_MIN = 5.0
AGENT_MASS = 5.0
BACKWARD_FX_THRESHOLD = -34.0
BACKWARD_SPEED_MAX = 100.0
EXIT_X_MIN = 15.0
TIME_STEP = 1.0 / 60.0


def _control_cfg(_sandbox):
    return {
        "act_lo": ACTIVATION_X_MIN,
        "act_hi": ACTIVATION_X_MAX,
        "bfx": BACKWARD_FX_THRESHOLD,
        "bspd": BACKWARD_SPEED_MAX,
    }


class Memory:
    def __init__(self):
        self.data = {}
    def clear(self):
        self.data = {}


MEM = Memory()


def _weight_comp(sandbox):
    gy = float(sandbox.world.gravity[1])
    return float(AGENT_MASS) * abs(gy)


def _exit_x_min(_sandbox):
    return float(EXIT_X_MIN)


def build_agent(sandbox):
    MEM.clear()
    return sandbox.get_agent_body()


def agent_action(sandbox, agent_body, step_count):
    if "initial_state" not in MEM.data:
        MEM.data["initial_state"] = {
            "phase": "APPROACH",
            "t": 0,
            "lx": None,
            "ly": None,
            "vx": 0.0,
            "vy": 0.0,
            "unlock_steps": 0,
            "total_impulse": 0.0,
            "hold_steps": 0,
